 34→/// Progress events emitted during workflow execution.
 35→#[derive(Debug)]
 36→pub enum RunProgress<'a> {
 37→    /// A step is about to start.
 38→    StepStarting {
 39→        name: &'a str,
 40→        index: usize,
 41→        total: usize,
 42→    },
 43→    /// A step finished.
 44→    StepFinished {
