            PromptOption {
                label: "Yes".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No".to_string(),
                value: "no".to_string(),
            },
            PromptOption {
                label: "Maybe".to_string(),
                value: "maybe".to_string(),
            },
        ];
        assert!(!is_yes_no(&options));
    }

    #[test]
    fn select_theme_creates_without_panic() {
        let theme = select_theme();
        // Verify the theme object can be used (smoke test)
        drop(theme);
    }

    #[test]
    fn map_eof_to_interrupted_converts_unexpected_eof() {
        use std::io::ErrorKind;
        let eof_err = std::io::Error::new(ErrorKind::UnexpectedEof, "end of file");
        let result: Result<PromptResult> = Err(BivvyError::Io(eof_err));
        let mapped = map_eof_to_interrupted(result);
        assert!(matches!(mapped, Err(BivvyError::Interrupted)));
    }

    #[test]
    fn map_eof_to_interrupted_converts_io_interrupted() {
        use std::io::ErrorKind;
        let err = std::io::Error::new(ErrorKind::Interrupted, "read interrupted");
        let result: Result<PromptResult> = Err(BivvyError::Io(err));
        let mapped = map_eof_to_interrupted(result);
        assert!(matches!(mapped, Err(BivvyError::Interrupted)));
    }

    #[test]
    fn map_eof_to_interrupted_passes_through_other_io_errors() {
        use std::io::ErrorKind;
        let other_err = std::io::Error::new(ErrorKind::PermissionDenied, "denied");
        let result: Result<PromptResult> = Err(BivvyError::Io(other_err));
        let mapped = map_eof_to_interrupted(result);
        assert!(matches!(mapped, Err(BivvyError::Io(_))));
    }

    #[test]
    fn map_eof_to_interrupted_passes_through_ok() {
        let result: Result<PromptResult> = Ok(PromptResult::Bool(true));
        let mapped = map_eof_to_interrupted(result);
        assert!(mapped.is_ok());
    }

    #[test]
    fn map_eof_to_interrupted_passes_through_non_io_errors() {
        let result: Result<PromptResult> = Err(BivvyError::ConfigValidationError {
            message: "test".to_string(),
        });
        let mapped = map_eof_to_interrupted(result);
        assert!(matches!(
            mapped,
            Err(BivvyError::ConfigValidationError { .. })
        ));
    }
}

