/// Convert EOF or interrupted IO errors into `BivvyError::Interrupted`.
///
/// When a user presses Ctrl+D (or the terminal closes), the underlying
/// read returns `UnexpectedEof` or `Interrupted`. This converts those
/// into a clean `Interrupted` error for user-friendly handling.
fn map_eof_to_interrupted(result: Result<PromptResult>) -> Result<PromptResult> {
    result.map_err(|e| match &e {
        BivvyError::Io(io_err)
            if io_err.kind() == ErrorKind::UnexpectedEof
                || io_err.kind() == ErrorKind::Interrupted =>
        {
            BivvyError::Interrupted
        }
        _ => e,
    })
}

/// Prompt the user for input.
pub fn prompt_user(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    let result = match &prompt.prompt_type {
        PromptType::Confirm => prompt_confirm(prompt, term),
        PromptType::Input => prompt_input(prompt, term),
        PromptType::Select { options } => prompt_select(prompt, options, term),
        PromptType::MultiSelect { options } => prompt_multiselect(prompt, options, term),
    };
    map_eof_to_interrupted(result)
}

